"""Truques (magias de nível 0). Tradução não oficial do SRD 5.2.1."""


def CU(d):
    n, f = d.split("d")
    return "\n\nMelhoria de truque. O dano aumenta em %s nos níveis 5 (2d%s), 11 (3d%s) e 17 (4d%s)." % (d, f, f, f)


